    highlights: [["York Minster", "Saatli giriş ve kule tırmanışı ayrı olabilir; kule dar merdiven ve hava koşuluna bağlıdır. Evensong ibadettir, ücretsiz tur alternatifi gibi davranmayın."], ["Surlar ve Clifford's Tower", "Surları tam tur yürümek 2 saate yaklaşabilir; Minster–Bootham veya Micklegate kesimini seçin. Clifford's Tower Yahudi tarihi bağlamıyla görülmeli."], ["Jorvik ve müzeler", "Jorvik saatli bilet; National Railway Museum ücretsiz/rezervasyonlu olabilir ve galeri yenilemeleri vardır. Bir güne ikisini sıkıştırmadan ilgiye göre seçin."]],
    neighborhoods: ["**City Centre** simgeler; **Micklegate** pub ve istasyon; **Bootham** sakin/Minster; **Bishy Road** yerel kafe ve bağımsız dükkan."], stay: ["Bir gece için istasyon–Micklegate veya Bootham. Merkez tarihî binada merdiven, hafta sonu pub gürültüsü ve otoparkı kontrol edin."],
    cuisine: ["Yorkshire pudding ana yemek değil roast'ın parçasıdır; Yorkshire curd tart, parkin ve yerel ale deneyin. Bettys afternoon tea turistik ama tarihî; rezervasyon/sıra modelini kontrol edin.", "Shambles Market hızlı öğle, Fossgate restoran, Micklegate pub için iyi kümelerdir."],
    nightlifeShopping: ["Fossgate/Walmgate bağımsız bar, Micklegate pub, Stonegate tarihî merkez için. Çikolata York sanayi tarihinin parçasıdır; yerel üretici, Yorkshire tea ve kitap/antikada özgün dükkânları seçin."],
    dayTrips: ["North York Moors ve Whitby araç/tur veya mevsimsel demiryolu bağlantısıyla tam gün; Harrogate kolay tren; Castle Howard otobüs/tur takvimine bağlıdır."], seasons: ["İlkbahar/sonbahar surlar için iyi; yaz kalabalık, kış Christmas Market yoğun. Yağmur veya buzda sur bölümleri kapanabilir."], budget: ["Minster, Jorvik ve kuleler birikir; Railway Museum ve şehir yürüyüşü dengeler. York Pass yalnız ziyaret listeniz netse değerlidir."], avoid: ["Sur kapanışını görmezden gelmeyin. Shambles'da yalnız temalı dükkân kuyruğunda zaman kaybetmeyin. Ghost walk'ta tarih ile tiyatroyu ayırın."],
    places: [["Bettys", "St Helen's Square", "Afternoon tea", "Yorkshire pastane geleneğini gösterişli salonda deneyimlemek için.", "Yüksek"], ["Skosh", "Micklegate", "Çağdaş küçük tabaklar", "York'un modern yemek sahnesi için.", "Yüksek", "Rezervasyon yapın."], ["The House of the Trembling Madness", "Stonegate", "Ale ve pub yemekleri", "Tarihî üst katta yerel bira seçkisi için.", "Orta"], ["Shambles Kitchen", "Shambles", "Sandviç ve hızlı öğle", "Dar sokak turunda hızlı, doyurucu mola.", "Ekonomik"], ["Spring Espresso", "Fossgate", "Nitelikli kahve", "Bağımsız cadde yürüyüşünde iyi kahve.", "Orta"], ["Roots", "Clifton", "Mevsimsel fine dining", "Yorkshire ürününü uzun, özel menüde görmek için.", "Yüksek", "Çok önceden ayırın."]],
    itinerary: [["1. Gün — Minster ve surlar", "Minster", "Surlar–Shambles", "Fossgate pub"], ["2. Gün — Viking/demiryolu", "Jorvik veya Railway", "Clifford's–müzeler", "Micklegate"], ["3. Gün — Whitby/Moors", "Erken tur/tren", "Tam gün", "York dönüş"]],
