    highlights: [["Kelvingrove ve West End", "Kelvingrove ücretsiz/geniş; iki katı seçerek gezin. University cloisters, Hunterian ve Ashton Lane'i aynı bölgede bağlayın."], ["Mackintosh ve merkez", "Glasgow School of Art yangın/restorasyon nedeniyle erişime açık olmayabilir; Mackintosh at the Willow, Lighthouse durumunu ve House for an Art Lover'ı resmî sayfadan kontrol edin."], ["Burrell ve Southside", "Burrell Collection Pollok Country Park içindedir; tren/otobüs ve park yürüyüşüyle yarım gün. Southside bağımsız yemek ve Queen's Park manzarası sunar."], ["Clyde ve müzik", "Riverside Museum, Finnieston ve Hydro çevresi aynı gün. Konser için resmî bilet ve son ulaşım planı yapın."]],
    neighborhoods: ["**City Centre/Merchant City** ulaşım/gece; **West End** müze–üniversite; **Finnieston** restoran/konser; **Southside** yerel ve bütçe; **Dennistoun** bağımsız kafe/pub."], stay: ["İlk ziyaret merkez veya West End Subway hattı. Konser gecesinde Hydro erişimi, hafta sonu Sauchiehall gürültüsü; eski tenement'ta merdiven/ısıtma kontrol edin."],
    cuisine: ["Haggis, cullen skink, Scotch pie ve tablet İskoç klasikler; Glasgow curry, vegan ve modern bistro sahnesinde güçlüdür. Deep-fried Mars bar merak ürünü, günlük şehir mutfağının özeti değildir.", "Pub/bar servisinde bardan sipariş yaygın; restoran service charge satırını kontrol edin."],
    nightlifeShopping: ["Sauchiehall canlı müzik, Merchant City LGBTQ+/bar, Finnieston kokteyl/restoran, West End pub için. Tartan/kaşmirde etiket; plak ve tasarımda bağımsız dükkânlar; Barras hafta sonu pazar programı."],
    dayTrips: ["Loch Lomond Balloch trenle kolay giriş; Stirling tarih; Arran feribot + trenle uzun ama mümkün. Highlands için Glasgow iyi çıkış üssüdür; günübirlikte sürüş süresini okuyun."], seasons: ["Mayıs–haziran uzun gün; eylül iyi. Yağmur yıl boyu, kış karanlık ve rüzgârlı. Celtic Connections gibi festival/Old Firm maçları oteli etkiler."], budget: ["Büyük müzelerin ücretsiz olması avantaj; konser, gece ve taksi maliyeti eklenir. Subway günlük bilet ve tekli kullanımınızı karşılaştırın."], avoid: ["Central ve Queen Street istasyonunu karıştırmayın. Old Firm maç gününde forma/renk ve pub atmosferine duyarlı olun; kalabalık güvenlik yönlendirmesini izleyin. Kapalı Mackintosh alanına güvenerek plan yapmayın."],
    places: [["Ubiquitous Chip", "West End", "Modern İskoç mutfağı", "Uzun ömürlü, atmosferli bir yerel ürün akşamı.", "Yüksek"], ["The Gannet", "Finnieston", "Mevsimsel İskoç", "Çağdaş Glasgow mutfağını özenli menüde görmek için.", "Yüksek", "Rezervasyon yapın."], ["Mother India’s Café", "West End", "Hint küçük tabaklar", "Glasgow curry kültürünü paylaşmalı tabaklarla denemek için.", "Orta"], ["Ox and Finch", "Finnieston", "Küçük tabaklar", "Canlı, modern ve grup dostu akşam.", "Orta"], ["Papercup Coffee", "West End", "Nitelikli kahve", "Great Western Road sabahında bağımsız kahve.", "Orta"], ["The Pot Still", "City Centre", "Whisky pub", "Geniş seçkide bilgili servisle dram denemek için.", "Orta", "Tadım sonrası araç kullanmayın."]],
    itinerary: [["1. Gün — West End", "Kelvingrove", "Üniversite/Hunterian", "Ashton Lane"], ["2. Gün — Merkez ve Clyde", "Mackintosh seçkisi", "Riverside–Finnieston", "Canlı müzik"], ["3. Gün — Burrell/Southside", "Burrell", "Queen's Park/mahalle", "Merchant City"]],
    practical: [["İki istasyon", "Central ve Queen Street farklı yönleri taşır."], ["Mackintosh", "Restorasyon/açılışı doğrulayın."], ["Konser", "Son tren/Subway saatini kaydedin."], ["Yağmur", "Müze yedeği hazır tutun."]],
