    itinerary: [["1. Gün — Titanic", "Titanic Quarter", "Maritime Mile", "Cathedral Quarter"], ["2. Gün — Şehir tarihi", "City Hall–Market", "Ulster Museum/duvar resmi turu", "Tarihî pub"], ["3. Gün — Causeway", "Erken kıyı turu", "Giant's Causeway ve seçilmiş duraklar", "Belfast dönüş"]],
    practical: [["İki havalimanı", "BHD ve BFS transferini ayırın."], ["Pazar günü", "St George's açık günlerini kontrol edin."], ["Duyarlı tarih", "Bağlamlı rehber ve fotoğraf izni."], ["Kıyı hava", "Rüzgâr/yağmur için yedek katman."]],
