    related: [["Glasgow", "Belfast–Glasgow bağlantısı", "Uçuş/feribotla İskoç müzik şehri."], ["Edinburgh", "Belfast'tan Edinburgh'a", "Kale ve Old Town."], ["Liverpool", "İrlanda Denizi'nden Liverpool'a", "Liman ve müzik mirası."], ["İskoçya Highlands", "Kuzeyin doğa rotaları", "Glencoe ve loch manzaraları."]], sourceName: "VisitBritain — Belfast", sourceUrl: "https://www.visitbritain.com/en/destinations/northern-ireland/belfast", transportSource: { name: "Translink", url: "https://www.translink.co.uk/" },
